import { Component } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { MisCompras } from 'src/app/models/mis-compras';
import { UsuarioService } from 'src/app/services/usuario.service';
import { Usuario } from 'src/app/models/usuario';

@Component({
  selector: 'app-ej42',
  templateUrl: './ej42.component.html',
  styleUrls: ['./ej42.component.css']
})
export class Ej42Component{

  public maxPrecio: number = 0;
  public nombreProducto: string = "";
  public usuariosConProductoCaro: string[] = [];

  constructor(public usuarioService: UsuarioService, public misComprasService: MisComprasService) {
    this.cargarDatos();
  }

  cargarDatos(): void {
    this.usuarioService.getUsuarios().subscribe((usuarios: Usuario[]) => {
      usuarios.forEach((usuario) => {
        this.misComprasService.obtenerComprasUsuario(usuario.email).subscribe((compras: MisCompras[]) => {
          compras.forEach((compra) => {
            compra.productos.forEach((producto) => {
              if (producto.precio > this.maxPrecio) {
                // Nuevo precio máximo encontrado, resetear lista y actualizar máximo
                this.maxPrecio = producto.precio;
                this.nombreProducto = producto.nombreProd;
                this.usuariosConProductoCaro = [usuario.nombreCompleto];
              } else if (producto.precio === this.maxPrecio) {
                // Producto igual al precio máximo, agregar si no está ya en la lista
                if (!this.usuariosConProductoCaro.includes(usuario.nombreCompleto)) {
                  this.usuariosConProductoCaro.push(usuario.nombreCompleto);
                }
              }
            });
          });
        });
      });
    });
  }
}
<p>Producto más caro: {{ nombreProducto }}</p>
<p>Precio máximo: {{ maxPrecio }} €</p>
  <li *ngFor="let usuario of usuariosConProductoCaro">
    {{ usuario }}
  </li>
